const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define northeastern Pacific Ocean region
  const region = ee.Geometry.Rectangle([-130, 30, -110, 50]);

  // Load OI SST v2 dataset
  const sstCollection = ee.ImageCollection('NOAA/OI_SST_V2');

  // August 2019 data
  const aug2019 = sstCollection
    .filterDate('2019-08-01', '2019-08-31')
    .filterBounds(region);

  const size2019 = aug2019.size().getInfo();
  console.log(`August 2019 Images: ${size2019}`);

  if (size2019 === 0) {
    console.log('No data for August 2019.');
    console.log('C1');
    return;
  }

  // August 1985-2012 climatology
  const aug1985to2012 = sstCollection
    .filter(ee.Filter.calendarRange(8, 8, 'month'))
    .filter(ee.Filter.calendarRange(1985, 2012, 'year'))
    .filterBounds(region);

  const sizeClim = aug1985to2012.size().getInfo();
  console.log(`August 1985-2012 Images: ${sizeClim}`);

  if (sizeClim === 0) {
    console.log('No data for August 1985-2012 climatology.');
    console.log('C1');
    return;
  }

  // Mean SST for August 2019
  const img2019 = aug2019.mean();
  const mean2019 = img2019.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 25000,
    maxPixels: 1e9
  }).get('analysed_sst').getInfo();

  // Mean SST for August 1985-2012 climatology
  const imgClim = aug1985to2012.mean();
  const meanClim = imgClim.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 25000,
    maxPixels: 1e9
  }).get('analysed_sst').getInfo();

  // Validate results
  if (mean2019 === null || meanClim === null || isNaN(mean2019) || isNaN(meanClim)) {
    console.log('Calculation failed: null or NaN values.');
    console.log('C3');
    return;
  }

  // Convert from Kelvin to Celsius if necessary (OI SST is in Kelvin)
  const temp2019_C = mean2019 - 273.15;
  const tempClim_C = meanClim - 273.15;

  // Validate temperature ranges
  if (temp2019_C < -10 || temp2019_C > 40 || tempClim_C < -10 || tempClim_C > 40) {
    console.log('Invalid temperature range detected.');
    console.log('C3');
    return;
  }

  console.log(`Aug 2019 Mean SST: ${temp2019_C.toFixed(2)}°C`);
  console.log(`Aug 1985-2012 Mean SST: ${tempClim_C.toFixed(2)}°C`);
  console.log(`Difference: ${(temp2019_C - tempClim_C).toFixed(2)}°C`);

  // Answer: Is 2019 cooler than climatology?
  if (temp2019_C < tempClim_C) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
